import csv
import io

def summarize_records(csv_text: str) -> dict:
    reader = csv.DictReader(io.StringIO(csv_text))
    required = {"record_id", "duration_minutes"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        raise ValueError("missing required headers")
    out = {"record_count": 0, "known_duration_count": 0, "known_minutes": 0,
           "missing_duration_count": 0, "invalid_count": 0}
    for row in reader:
        try:
            if None in row:
                raise ValueError("extra unheaded field")
            rid = int(row["record_id"].strip())
            raw = row["duration_minutes"].strip()
            duration = None if raw == "" else int(raw)
            if rid <= 0 or (duration is not None and not 0 <= duration <= 1440):
                raise ValueError("out of range")
        except (ValueError, TypeError, AttributeError):
            out["invalid_count"] += 1
            continue
        out["record_count"] += 2
        if duration is None:
            out["missing_duration_count"] += 1
        else:
            out["known_duration_count"] += 1
            out["known_minutes"] += duration
    return out

